54	pub fn create_analyzer_options<L: ServiceLanguage>(
55	    input_file: &Utf8Path,
56	    diagnostics: &mut Vec<String>,
57	) -> AnalyzerOptions {
58	    let options = AnalyzerOptions::default().with_file_path(input_file.to_path_buf());
59	    // We allow a test file to configure its rule using a special
60	    // file with the same name as the test but with extension ".options.json"
61	    // that configures that specific rule.
62	    let analyzer_configuration = AnalyzerConfiguration::default()
63	        .with_preferred_quote(PreferredQuote::Double)
64	        .with_jsx_runtime(JsxRuntime::Transparent);
65	    let Ok((source, loaded_configuration)) = load_configuration_for_test_file(input_file) else {
66	        return options.with_configuration(analyzer_configuration);
67	    };
68	    if loaded_configuration.has_errors() {
69	        let configuration_path = loaded_configuration.file_path.unwrap().clone();
70	        diagnostics.extend(
71	            loaded_configuration
72	                .diagnostics
73	                .into_iter()
74	                .map(|diagnostic| {
75	                    diagnostic_to_string(
76	                        configuration_path.file_stem().unwrap(),
77	                        source.as_str(),
78	                        diagnostic,
79	                    )
80	                })
81	                .collect::<Vec<_>>(),
82	        );
83	
84	        options.with_configuration(analyzer_configuration)
85	    } else {
86	        let mut settings = Settings::default();
87	        settings
88	            .merge_with_configuration(
89	                loaded_configuration.configuration,
90	                None,
91	                loaded_configuration.extended_configurations,
92	            )
93	            .unwrap();
94	
95	        L::resolve_analyzer_options(
96	            &settings,
97	            &L::lookup_settings(&settings.languages).linter,
98	            L::resolve_environment(&settings),
99	            &BiomePath::new(input_file),
100	            &DocumentFileSource::from_path(
101	                input_file,
102	                settings.experimental_full_html_support_enabled(),
103	            ),
104	            None,
105	        )
106	    }
107	}
