110	    input_file: &Utf8Path,
111	) -> Option<(Configuration, Vec<(Utf8PathBuf, Configuration)>)> {
112	    let fs = OsFileSystem::new(input_file.parent().unwrap().to_path_buf());
113	    let source = fs.read_file_from_path(input_file).ok()?;
114	
115	    let path_hint = ConfigurationPathHint::FromUser(input_file.to_path_buf());
116	    let (_, loaded_configuration) = load_configuration(&fs, path_hint)
117	        .map(|configuration| (source, configuration))
118	        .ok()?;
119	
