130	pub fn load_configuration_for_test_file(
131	    input_file: &Utf8Path,
132	) -> Result<(String, LoadedConfiguration), WorkspaceError> {
133	    let fs = OsFileSystem::new(input_file.parent().unwrap().to_path_buf());
134	    let options_file = input_file.with_extension("options.json");
135	    let source = fs.read_file_from_path(&options_file);
136	    match source {
