use biome_console::markup;
use biome_css_syntax::{
    AnyCssRelativeSelector, AnyCssSelector, CssNestedQualifiedRule, CssQualifiedRule, CssRoot,
    CssSyntaxKind,
};
use biome_rowan::{AstNode, AstSeparatedList, TextRange};
use biome_rule_options::no_excessive_selector_classes::NoExcessiveSelectorClassesOptions;

declare_lint_rule! {
    /// Disallow selectors with too many class selectors.
    ///
    /// Selectors that chain many class selectors together are harder to read,
    /// override, and reuse. This rule flags each individual selector whose total
    /// number of class selectors exceeds the configured maximum.
    ///
    /// Class selectors are counted across the whole selector, including those
    /// nested inside pseudo-class functions such as `:not()`, `:is()`, `:has()`,
    /// and `:nth-child(... of ...)`. Each selector in a comma-separated list and
    /// each nested rule is evaluated independently.
    ///
    /// The rule does nothing unless the `maxClasses` option is configured.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// The following example will show a diagnostic when `maxClasses` is set to 1:
    ///
    /// ```json,options
    /// {
    ///     "options": {
    ///        "maxClasses": 1
    ///     }
    /// }
    /// ```
    /// ```css,expect_diagnostic,use_options
    /// .a.b {
    ///     color: red;
    /// }
    /// ```
    ///
    /// ### Valid
    ///
    /// ```css,use_options
    /// .a {
    ///     color: red;
    /// }
    /// ```
    ///
    /// ## Options
    ///
    /// ### `maxClasses`
    ///
    /// This option sets the maximum number of class selectors allowed in a single
    /// selector. When it is not set, the rule does not report any diagnostic.
    ///
    pub NoExcessiveSelectorClasses {
        version: "next",
        name: "noExcessiveSelectorClasses",
        language: "css",
        recommended: false,
    }
}

pub struct RuleState {
    range: TextRange,
    count: usize,
}

impl Rule for NoExcessiveSelectorClasses {
    type Query = Ast<CssRoot>;
    type State = RuleState;
    type Signals = Vec<Self::State>;
    type Options = NoExcessiveSelectorClassesOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let Some(max_classes) = ctx.options().max_classes else {
            return Vec::new();
        };
        let max_classes = max_classes as usize;

        let mut signals = Vec::new();
        for node in ctx.query().syntax().descendants() {
            match node.kind() {
                CssSyntaxKind::CSS_QUALIFIED_RULE => {
                    let Some(rule) = CssQualifiedRule::cast(node) else {
                        continue;
                    };
                    for selector in rule.prelude().iter().flatten() {
                        check_selector(&selector, max_classes, &mut signals);
                    }
                }
                CssSyntaxKind::CSS_NESTED_QUALIFIED_RULE => {
                    let Some(rule) = CssNestedQualifiedRule::cast(node) else {
                        continue;
                    };
                    for relative in rule.prelude().iter().flatten() {
                        let AnyCssRelativeSelector::CssRelativeSelector(relative) = relative else {
                            continue;
                        };
                        if let Ok(selector) = relative.selector() {
                            check_selector(&selector, max_classes, &mut signals);
                        }
                    }
                }
                _ => {}
            }
        }

        signals
    }

    fn diagnostic(ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let max_classes = ctx.options().max_classes? as usize;
        let count = state.count;
        let class_selectors = if max_classes == 1 {
            "class selector"
        } else {
            "class selectors"
        };

        Some(
            RuleDiagnostic::new(
                rule_category!(),
                state.range,
                markup! {
                    "Expected this selector to have no more than "{max_classes}" "{class_selectors}", but found "{count}"."
                },
            )
            .note(markup! {
                "Selectors with too many chained classes are harder to read, override, and reuse."
            })
            .note(markup! {
                "Reduce the number of class selectors in this selector, or split it into simpler selectors."
            }),
        )
    }
}

/// Counts the class selectors in a single selector and records a violation when
/// the count exceeds `max_classes`. Selectors containing an SCSS interpolation
/// are skipped because their final shape is only known at build time.
fn check_selector(selector: &AnyCssSelector, max_classes: usize, signals: &mut Vec<RuleState>) {
    let syntax = selector.syntax();

    if syntax
        .descendants()
        .any(|node| node.kind() == CssSyntaxKind::SCSS_INTERPOLATION)
    {
        return;
    }

    let count = syntax
        .descendants()
        .filter(|node| node.kind() == CssSyntaxKind::CSS_CLASS_SELECTOR)
        .count();

    if count > max_classes {
        signals.push(RuleState {
            range: selector.range(),
            count,
        });
    }
}
